  "regions": [
    {
      "id": "r2",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "इत्थैश्वर्यबलान्वितोपि बलभिद्भग्नः परैः संगरे",
          "end": "line"
        },
        {
          "n": 2,
          "text": "तद्व्यक्तं वरमेव दैवशरणं धिग्धिग्वृथा पौरुषम् ॥ ८८ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r3",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "कर्मायत्तं फलं पुंसां बुद्धिः कर्मानुसारिणी ।",
          "end": "line"
        },
        {
          "n": 2,
          "text": "तथापि सुधिया भाव्यं सुविचार्यैव कुर्वता ॥ ८९ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r4",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "खल्वाटो दिवसेश्वरस्य किरणैः संतापितो मस्तके",
          "end": "line"
        },
        {
          "n": 2,
          "text": "वाञ्छन्देशमनातपं विधिवशात्तालस्य मूलं गतः ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "तत्राप्यस्य महाफलेन पतता भग्नं सशब्दं शिरः",
          "end": "line"
        },
        {
          "n": 4,
          "text": "प्रायो गच्छति यत्र भाग्यरहितस्तत्रैव यान्त्यापदः ॥ ९० ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r5",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "शशिदिवाकरयोर्ग्रहपीडनं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "गजभुजंगमयोरपि बन्धनम् ।",
          "end": "line"
        },
        {
          "n": 3,
          "text": "मतिमतां च विलोक्य दरिद्रतां",
          "end": "line"
        },
        {
          "n": 4,
          "text": "विधिरहो बलवानिति मे मतिः ॥ ९१ ॥",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r6",
      "type": "verse",
      "lines": [
        {
          "n": 1,
          "text": "सृजति तावदशेषगुणाकरं",
          "end": "line"
        },
        {
          "n": 2,
          "text": "पुरुषरत्नमलंकरणं भुवः ।",
          "end": "line"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r7",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "(c) °त्थैश्च°; °त्थाश्च° W. T. N. P. R. °बला°; °सम°. K. Be.n. °पि;",
          "end": "space"
        },
        {
          "n": 2,
          "text": "°त्ये Bo.n.(?) बलभिद्भ°; मघवा भ° L. D. बलिभिर्भ°. C. W. T. Be. मघवान्भ°",
          "end": "space"
        },
        {
          "n": 3,
          "text": "Bo.n. (d) °द्व्य; °द्यु°. S. Be. K. X. D. N. Bo. (orig. Bo.n.) वरमेव",
          "end": "space"
        },
        {
          "n": 4,
          "text": "दैव°; ननु दैवमेव S. K. Be. X. D. Bo. (orig. Bo.n.) L. P. R. N.",
          "end": "space"
