    {
      "id": "r8",
      "type": "apparatus_entry",
      "lines": [
        {
          "n": 1,
          "text": "XC. (a) °ल्व°; °र्वा° N. °तो; °ते. Be.n. N. (b) वाञ्छ°; गच्छ°.",
          "end": "space"
        },
        {
          "n": 2,
          "text": "N. विधिवशात्; द्रुतगतिः N. तालस्य; बिल्वस्य K. Be. Bo. W. P. R. L. (in",
          "end": "space"
        },
        {
          "n": 3,
          "text": "margin ताड) (c) °त्राप्यस्य; °त्राप्याशु L. W. °त्रोच्चैः T. °हा°; °हता.",
          "end": "space"
        },
        {
          "n": 4,
          "text": "T. (d) भाग्यरहितः; दैवहतकः N. तत्रैव यान्त्यापदः; तत्रापदां भाजनम्. W. T.",
          "end": "space"
        },
        {
          "n": 5,
          "text": "(where the other reading is noted) P. R.",
          "end": "space"
        }
      ],
      "uncertain": false,
      "note": null
    },
    {
      "id": "r9",
      "type": "apparatus_entry",
